-- scripts/add_greek_monster_groups.sql
-- Named members of Greek monster-groups (Cyclopes, Hekatoncheires, Gorgons, Harpies,
-- Graeae) from Hesiod Theogony (Evelyn-White). Verbatim, substring-gated; held/colliding names skipped.

BEGIN;

ON CONFLICT (entity_id) DO NOTHING;

ON CONFLICT (citation_id) DO UPDATE SET quote=EXCLUDED.quote;


-- quote fixes (strip Gutenberg line-markers; Euryale → Gorgon passage):
UPDATE entity_citations SET quote='And again, she bare the Cyclopes, overbearing in spirit, Brontes, and Steropes and stubborn-hearted Arges 1606, who gave Zeus the thunder and made the thunderbolt: in all else they were like the gods, but one eye only was se' WHERE citation_id='CIT_BRONTES_THEOG';
UPDATE entity_citations SET quote='And again, she bare the Cyclopes, overbearing in spirit, Brontes, and Steropes and stubborn-hearted Arges 1606, who gave Zeus the thunder and made the thunderbolt: in all else they were like the gods, but one eye only was set in the midst' WHERE citation_id='CIT_STEROPES_THEOG';
UPDATE entity_citations SET quote='And again, she bare the Cyclopes, overbearing in spirit, Brontes, and Steropes and stubborn-hearted Arges 1606, who gave Zeus the thunder and made the thunderbolt: in all else they were like the gods, but one eye only was set in the midst of their fore-heads.' WHERE citation_id='CIT_ARGES_THEOG';
UPDATE entity_citations SET quote='And again, three other sons were born of Earth and Heaven, great and doughty beyond telling, Cottus and Briareos and Gyes, presumptuous children.' WHERE citation_id='CIT_COTTUS_THEOG';
UPDATE entity_citations SET quote='And again, three other sons were born of Earth and Heaven, great and doughty beyond telling, Cottus and Briareos and Gyes, presumptuous children.' WHERE citation_id='CIT_BRIAREUS_THEOG';
UPDATE entity_citations SET quote='And again, three other sons were born of Earth and Heaven, great and doughty beyond telling, Cottus and Briareos and Gyes, presumptuous children.' WHERE citation_id='CIT_GYES_THEOG';
UPDATE entity_citations SET quote='an in the frontier land towards Night where are the clear-voiced Hesperides, Sthenno, and Euryale, and Medusa who suffered a woeful fate: she was mortal, but the two were undying and grew not old.' WHERE citation_id='CIT_EURYALE_THEOG';
UPDATE entity_citations SET quote='And Thaumas wedded Electra the daughter of deep-flowing Ocean, and she bare him swift Iris and the long-haired Harpies, Aello (Storm-swift) and Ocypetes (Swift-flier) who on their swift wings keep pace with the blasts of the winds and the birds; for quick as time they dart along.' WHERE citation_id='CIT_AELLO_THEOG';
UPDATE entity_citations SET quote='And again, Ceto bare to Phorcys the fair-cheeked Graiae, sisters grey from their birth: and both deathless gods and men who walk on earth call them Graiae, Pemphredo well-clad, and saffron-robed Enyo, and the Gorgons who dwell beyond glorious Ocean in the frontier land towards Night where are the clear-voiced Hesperides, St' WHERE citation_id='CIT_PEMPHREDO_THEOG';
COMMIT;
